import * as THREE from 'three/webgpu';
import {
  MeshBasicNodeMaterial,
  texture,
  uv,
  vec4,
  mul,
  sub,
  add,
  float,
  mix,
  vec2
} from 'three/tsl';
import { gsap } from 'gsap';
import { msdf } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {Array<number>} position
 * @property {Array<number>} rotation
 * @property {Array<number>} scale
 * @property {Array<string>} textContent
 * @property {Object} assets
 * @property {string} assets.imageUrl
 */

/**
 * @typedef {Object} NodeContext
 * @property {Object} textureLoader - has .load(url:string):THREE.Texture
 * @property {Object} fontAtlas    - MSDF font atlas texture / utilities
 * @property {Object} primitives   - map of primitive functions
 */

/**
 * Create a billboarded sprite that displays an accent texture with
 * overlaid MSDF text.
 *
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode (config, ctx) {
  // geometry sizing – use the atlas region aspect ratio
  const atlasRegion = { w: 512, h: 320 };
  const aspect = atlasRegion.w / atlasRegion.h;
  const height = 0.34;                     // headline size from design tokens
  const width = height * aspect;

  const geometry = new THREE.PlaneGeometry(width, height);

  // Load the accent texture (no atlas offset needed – region starts at 0,0)
  const accentTexture = ctx.textureLoader.load(config.assets?.imageUrl ?? '/prism-mock/home/nodes/floating-accent.png');
  accentTexture.needsUpdate = true;
  accentTexture.minFilter = THREE.LinearFilter;
  accentTexture.magFilter = THREE.LinearFilter;
  accentTexture.generateMipmaps = false;

  // Image node
  const imgNode = texture(accentTexture, uv());

  // MSDF text node
  const textString = (config.textContent && config.textContent[0]) || 'Journal';
  const textColor = new THREE.Color('#16161d');

  const textNode = msdf({
    text: textString,
    fontAtlas: ctx.fontAtlas,
    color: textColor,
    // Rough size – we scale via the surrounding plane height
    size: height,
    align: 'center',
    // No background so alpha drives the blend
    opacity: 1.0
  });

  // Composite: image under text, text over image where alpha > 0
  const oneMinusTextAlpha = sub(float(1.0), textNode.a);
  const bgPortion = mul(imgNode, oneMinusTextAlpha);
  const fgPortion = mul(textNode, textNode.a);
  const finalColor = add(bgPortion, fgPortion);

  const material = new MeshBasicNodeMaterial({
    colorNode: finalColor,
    transparent: true,
    depthWrite: false
  });

  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.fromArray(config.position ?? [0, 3, 0]);
  mesh.rotation.fromArray(config.rotation ?? [0, 0, 0]);
  mesh.scale.fromArray(config.scale ?? [1, 1, 1]);

  // Billboard – face the camera every frame
  mesh.onBeforeRender = (renderer, scene, camera) => {
    mesh.quaternion.copy(camera.quaternion);
  };

  // No interaction handlers required, but keep the structure
  mesh.userData.handlers = {};

  // Cleanup routine
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (accentTexture) accentTexture.dispose();
    // No GSAP timelines in this node, but kill any that might exist
    gsap.globalTimeline.clear(true);
  };

  return mesh;
}
